_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_event() {
    cat <<-'EOF'
	process:started	Process started
	process:online	Process became online
	process:stopped	Process stopped
	process:exited	Process exited
	process:crashed	Process crashed
	process:restarting	Process restarting
	process:errored	Process errored
	log:out	Line written to standard output
	log:err	Line written to standard error
	health:healthy	Health check passed
	health:unhealthy	Health check failed
	daemon:shutdown	Daemon shutting down
	EOF
}

_choice_logs_target() {
    _helper_oxmgr_process_name
    printf 'all\tPrint logs for every process\n'
}

_choice_process() {
    _helper_oxmgr_process_name
}

_choice_signal() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i <= NF; i++) {
            if ($i ~ /^SIG[A-Z][A-Z0-9]*$/) print $i
            else if ($i ~ /^[A-Z][A-Z0-9]*$/) print "SIG" $i
        }
    }'
}

_choice_target() {
    _helper_oxmgr_process_name
}

_helper_oxmgr_process_name() {
    local state
    state="$(_helper_oxmgr_state_file)" || return 0
    command jq -b -r '.processes // [] | .[] | select(.name != null and .name != "") | [.name, (.status // "")] | @tsv' "$state" 2>/dev/null
}

# Locate the persisted daemon state. Reading the state file avoids contacting the
# daemon, which the CLI would auto-spawn when it is not running.
_helper_oxmgr_state_file() {
    local dir
    for dir in "${OXMGR_HOME:-}" "${XDG_DATA_HOME:+$XDG_DATA_HOME/oxmgr}" "$HOME/.local/share/oxmgr" "$HOME/Library/Application Support/oxmgr"; do
        if [[ -n "$dir" && -f "$dir/state.json" ]]; then
            printf '%s\n' "$dir/state.json"
            return 0
        fi
    done
    return 1
}
